def semver_sort(versions):
    def parse_version(v):
        # Split on '+' first to separate build metadata
        if '+' in v:
            version_part, build_metadata = v.split('+', 1)
        else:
            version_part = v
            build_metadata = None

        # Split on '-' to separate pre-release
        if '-' in version_part:
            core_part, prerelease_part = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert to tuples: (is_numeric, numeric_value, string_value)
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier), identifier))
                else:
                    parsed_prerelease.append((1, 0, identifier))
        else:
            parsed_prerelease = None

        return (major, minor, patch, parsed_prerelease)

    def sort_key(v):
        parsed = parse_version(v)
        major, minor, patch, prerelease = parsed

        # For sorting: (major, minor, patch, has_prerelease, prerelease_identifiers)
        # Versions with prerelease sort before versions without
        if prerelease is None:
            # No prerelease: sort after any prerelease of same core version
            return (major, minor, patch, 1, [])
        else:
            # Has prerelease: sort before any non-prerelease of same core version
            return (major, minor, patch, 0, prerelease)

    # Stable sort using sort_key
    return sorted(versions, key=sort_key)

